function applicableAxes(){return axes.filter(a=>a.id!=='wealth'||state.profile.waqfInterest==='yes')}
function applicableQuestions(axisId){return (questions[axisId]||[]).filter(q=>!q.show||q.show(state.profile))}
function steps(){return [{id:'profile',title:'ملف العائلة',icon:'profile'},...applicableAxes().map(a=>({id:a.id,title:a.title,icon:a.icon})),{id:'result',title:'النتيجة',icon:'report'}]}
function renderStepTabs(){const s=steps();$('stepTabs').innerHTML=s.map((x,i)=>`<button class="step-tab ${i===state.step?'active':''} ${i<state.step?'done':''}" data-goto="${i}">${x.title}</button>`).join('');document.querySelectorAll('[data-goto]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.goto);if(i<=state.step||canAdvanceTo(i)){state.step=i;renderDiagnostic();save();scrollDiagnosticStepStart()}}))}
function updateProgress(){const s=steps();const pct=Math.round((state.step/(s.length-1))*100);$('progressFill').style.width=pct+'%';$('progressPercent').textContent=pct+'%';$('progressLabel').textContent=s[state.step]?.title||''}
function scrollDiagnosticStepStart(){requestAnimationFrame(()=>document.querySelector('.progress-shell')?.scrollIntoView({behavior:'smooth',block:'start'}))}
function profilePanel(){return `<div class="panel-title"><div class="axis-icon">${icon('profile')}</div><div><h3>ملف العائلة والشركة</h3><p>تحدد البيانات الأسئلة التي ستظهر بما يناسب حالة العائلة والشركة</p></div></div><div class="form-grid">
 ${field('familyName','اسم العائلة أو الشركة','text','اختياري')}
 ${selectField('generation','الجيل الحالي',[['','اختر'],['1','الجيل الأول'],['2','الجيل الثاني'],['3','الجيل الثالث'],['4','الجيل الرابع فأكثر']])}
 ${selectField('owners','عدد الملاك',[['','اختر'],['1-3','1 إلى 3'],['4-10','4 إلى 10'],['11-30','11 إلى 30'],['31+','أكثر من 30']])}
 ${selectField('branches','عدد الفروع العائلية',[['','اختر'],['1','فرع واحد'],['2','فرعان'],['3-5','3 إلى 5'],['6+','أكثر من 5']])}
 ${selectField('legalForm','الشكل النظامي',[['','اختر'],['llc','ذات مسؤولية محدودة'],['jsc','مساهمة'],['sjsc','مساهمة مبسطة'],['holding','شركة قابضة'],['other','شكل آخر']])}
 ${selectField('board','مجلس الإدارة',[['','اختر'],['none','غير موجود'],['informal','موجود دون توثيق'],['formal','مجلس قائم ومعتمد']])}
 ${selectField('familyEmployees','عمل أفراد العائلة داخل الشركة',[['','اختر'],['none','لا يعمل أفراد من العائلة'],['few','عدد محدود'],['many','عدد كبير']])}
 ${selectField('waqfInterest','الوقف أو حوكمة الثروة',[['','اختر'],['yes','يوجد وقف أو رغبة جادة في دراسته'],['no','الموضوع خارج النطاق الحالي']])}
 ${selectField('conflict','وجود خلاف قائم',[['','اختر'],['none','لا يوجد خلاف مؤثر'],['early','تباين مبكر'],['active','خلاف قائم يحتاج معالجة']])}
 ${selectField('leadershipTransition','قرب انتقال القيادة',[['','اختر'],['far','أكثر من خمس سنوات'],['mid','خلال سنتين إلى خمس'],['near','خلال أقل من سنتين']])}
 ${selectField('holding','شركات تابعة أو شركة قابضة',[['','اختر'],['no','كيان واحد'],['yes','عدة شركات أو شركة قابضة']])}
 ${selectField('listing','الإدراج أو دخول مستثمر',[['','اختر'],['no','خارج الخطة الحالية'],['study','قيد الدراسة'],['active','مسار قائم']])}
 </div><div class="panel-actions panel-actions-end"><button class="btn primary" id="nextBtn">بدء المحاور</button></div>`}
function field(id,label,type,placeholder=''){return `<div class="form-group"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${escapeHtml(state.profile[id]||'')}" placeholder="${placeholder}"></div>`}
function selectField(id,label,opts){return `<div class="form-group"><label for="${id}">${label}</label><select id="${id}">${opts.map(([v,l])=>`<option value="${v}" ${state.profile[id]===v?'selected':''}>${l}</option>`).join('')}</select></div>`}
function axisPanel(axis){const qs=applicableQuestions(axis.id);return `<div class="panel-title"><div class="axis-icon">${icon(axis.icon)}</div><div><h3>${axis.title}</h3><p>${axis.desc}</p></div></div>${axis.id==='wealth'?'<div class="axis-note">يظهر هذا المحور لأن الملف أشار إلى وجود وقف أو رغبة جادة في دراسة حوكمة الثروة</div>':''}<div class="question-stack">${qs.map((q,i)=>questionCard(axis.id,q,i)).join('')}</div><div class="panel-actions"><button class="btn ghost" id="prevBtn">السابق</button><button class="btn primary" id="nextBtn">${isLastAxis(axis.id)?'إظهار النتيجة':'المحور التالي'}</button></div>`}
function questionCard(axisId,q,i){const key=axisId+'_'+q.id;const current=Object.prototype.hasOwnProperty.call(state.answers,key)?state.answers[key]:'unset';return `<article class="question-card"><div class="question-head"><div class="q-number">${i+1}</div><div><h4>${q.q}</h4><p>${q.d}</p></div></div><div class="answers">${answerOptions.map((a,n)=>{const val=a.value===null?'na':String(a.value);const selected=(current===null&&a.value===null)||String(current)===String(a.value);return `<button class="answer ${selected?'selected':''}" data-answer-key="${key}" data-answer="${val}">${a.label}</button>`}).join('')}</div></article>`}
function isLastAxis(id){const arr=applicableAxes();return arr[arr.length-1]?.id===id}
function validateProfile(){const required=['generation','owners','branches','legalForm','board','familyEmployees','waqfInterest','conflict','leadershipTransition','holding','listing'];for(const id of required){if(!state.profile[id]){toast('أكمل بيانات ملف العائلة والشركة');$(id)?.focus();return false}}return true}
function unanswered(axisId){return applicableQuestions(axisId).filter(q=>!Object.prototype.hasOwnProperty.call(state.answers,axisId+'_'+q.id))}
function canAdvanceTo(target){if(target===0)return true;if(!validateProfile())return false;const s=steps();for(let i=1;i<Math.min(target,s.length-1);i++){const id=s[i].id;if(unanswered(id).length){toast('أكمل إجابات المحاور السابقة');return false}}return true}
function syncProfileInputs(){document.querySelectorAll('#diagPanel input[id],#diagPanel select[id]').forEach(el=>{const value=latinDigits(el.value);if(el.value!==value)el.value=value;state.profile[el.id]=value})}
function bindPanel(){
 document.querySelectorAll('#diagPanel input,#diagPanel select').forEach(el=>el.addEventListener('input',()=>{const value=latinDigits(el.value);if(el.value!==value)el.value=value;state.profile[el.id]=value;state.result=null;save();if(el.id==='waqfInterest'){state.step=0;renderDiagnostic()}}));
 document.querySelectorAll('[data-answer-key]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.answerKey;state.answers[key]=b.dataset.answer==='na'?null:Number(b.dataset.answer);state.result=null;save();b.closest('.answers').querySelectorAll('.answer').forEach(x=>x.classList.toggle('selected',x===b))}));
 $('prevBtn')?.addEventListener('click',()=>{state.step=Math.max(0,state.step-1);renderDiagnostic();save();scrollDiagnosticStepStart()});
 $('nextBtn')?.addEventListener('click',()=>{const s=steps();if(state.step===0){syncProfileInputs();save();if(!validateProfile())return;state.step=1}else{const id=s[state.step].id;const left=unanswered(id);if(left.length){toast(`بقي ${left.length} من الأسئلة دون إجابة`);return}if(state.step===s.length-2){buildResult();state.step=s.length-1}else state.step++}renderDiagnostic();save();scrollDiagnosticStepStart()});
 $('printBtn')?.addEventListener('click',printReport);$('imageBtn')?.addEventListener('click',exportResultImage);$('restartBtn')?.addEventListener('click',()=>{if(confirm('سيتم حذف بيانات التشخيص الحالية')){localStorage.removeItem(STORAGE_KEY);state.step=0;state.profile={};state.answers={};state.result=null;renderDiagnostic()}})
}
function scoreAxis(axisId){const qs=applicableQuestions(axisId);let earned=0,max=0,answered=0;qs.forEach(q=>{const k=axisId+'_'+q.id;if(!Object.prototype.hasOwnProperty.call(state.answers,k))return;const v=state.answers[k];if(v===null)return;earned+=v*q.w;max+=4*q.w;answered++});return {score:max?Math.round(earned/max*100):null,answered,total:qs.length}}
function stage(score){const level=RESULT_LEVELS.find(x=>score>=x.min&&score<=x.max)||RESULT_LEVELS[0];return[level.label,level.desc]}
function valuationReadiness(){
 const inputs=[
  ['ownership_exit_policy','الاتفاق على حالات وآلية التقييم والتخارج'],
  ['ownership_valuation_recent','وجود تقييم مستقل حديث'],
  ['ownership_dividends','وضوح سياسة التوزيعات وإعادة الاستثمار'],
  ['company_conflict','حوكمة المعاملات مع الأطراف ذات العلاقة'],
  ['company_financial_separation','فصل حسابات المنشأة عن حسابات الملاك'],
  ['resilience_key_person','خفض الاعتماد على شخص محوري']
 ];
 const answered=inputs.filter(([key])=>Object.prototype.hasOwnProperty.call(state.answers,key)&&state.answers[key]!==null);
 const score=answered.length?Math.round(answered.reduce((sum,[key])=>sum+Number(state.answers[key]),0)/(answered.length*4)*100):0;
 const label=score>=75?'جاهزية مرتفعة للتقييم':score>=45?'جاهزية متوسطة وتحتاج إلى استكمال':'متطلبات أساسية قبل التقييم';
 const desc=score>=75?'البيانات والقواعد الأساسية جاهزة لبدء التقييم مع مقيم مستقل':score>=45?'ابدأ بتجهيز الملف واستكمل الوثائق قبل الاتفاق على نطاق التقييم':'ابدأ بتنظيم البيانات والملكية والحوكمة قبل تكليف المقيم';
 const gaps=inputs.filter(([key])=>!Object.prototype.hasOwnProperty.call(state.answers,key)||state.answers[key]===null||state.answers[key]<=2).map(([,text])=>text).slice(0,3);
 return {score,label,desc,gaps,answered:answered.length,total:inputs.length};
}
function valuationResultMarkup(v){
 const gaps=v.gaps.length?v.gaps.map(x=>`<li>${escapeHtml(x)}</li>`).join(''):'<li>مراجعة الجاهزية قبل القرارات الجوهرية</li>';
 return `<section class="valuation-result"><div class="valuation-result-head"><div><span>جزء من النتيجة</span><h3>جاهزية التقييم العادل</h3></div><strong>${v.score}%</strong></div><div class="valuation-result-body"><div><h4>${escapeHtml(v.label)}</h4><p>${escapeHtml(v.desc)}</p></div><div><small>أهم ما يحتاج إلى مراجعة</small><ul>${gaps}</ul></div></div><footer><span>المؤشر يقيس جاهزية البيانات والحوكمة ولا يعرض قيمة مالية</span><a href="${VALUATION_GUIDE_URL}" target="_blank" rel="noopener">فتح دليل التقييم العادل ${icon('external')}</a></footer></section>`;
}
function buildResult(){const axisScores=applicableAxes().map(a=>({...a,...scoreAxis(a.id)})).filter(x=>x.score!==null);const overall=Math.round(axisScores.reduce((s,x)=>s+x.score,0)/axisScores.length);const answered=axisScores.reduce((s,x)=>s+x.answered,0),total=axisScores.reduce((s,x)=>s+x.total,0);const confidence=Math.round(answered/Math.max(1,total)*100);const [label,desc]=stage(overall);const all=[];axisScores.forEach(a=>applicableQuestions(a.id).forEach(q=>{const k=a.id+'_'+q.id;if(!Object.prototype.hasOwnProperty.call(state.answers,k)||state.answers[k]===null)return;all.push({axis:a.title,axisId:a.id,q:q.q,value:state.answers[k],w:q.w,doc:q.doc,action:q.action,severity:(4-state.answers[k])*q.w})}));all.sort((a,b)=>b.severity-a.severity);const risks=all.slice(0,4);let docs=[...new Map(all.filter(x=>x.value<=2).map(x=>[x.doc,x])).values()].slice(0,5);let priorities=[...new Map(all.filter(x=>x.value<=2).map(x=>[x.action,x])).values()].slice(0,5);if(!docs.length)docs=[...new Map(all.map(x=>[x.doc,x])).values()].slice(0,3);if(!priorities.length)priorities=[...new Map(all.map(x=>[x.action,x])).values()].slice(0,3);const strongest=[...axisScores].sort((a,b)=>b.score-a.score)[0],weakest=[...axisScores].sort((a,b)=>a.score-b.score)[0];state.result={overall,confidence,label,desc,axisScores,risks,docs,priorities,strongest,weakest,valuation:valuationReadiness()};save()}
function resultPanel(){const r=state.result;if(!r||!r.valuation){buildResult();return resultPanel()}const familyName=String(state.profile.familyName||'').trim();const familyMarkup=familyName?`<div class="result-entity"><small>اسم العائلة أو الشركة</small><strong>${escapeHtml(familyName)}</strong></div>`:'';const axisHtml=r.axisScores.map(a=>`<article class="axis-result"><div class="axis-result-head"><h4>${a.title}</h4><strong>${a.score}%</strong></div><div class="bar"><span style="width:${a.score}%"></span></div></article>`).join('');const list=(arr,type)=>arr.map((x,i)=>`<div class="result-item"><div class="result-index">${i+1}</div><div><strong>${type==='risk'?x.q:type==='doc'?x.doc:x.action}</strong><span>${type==='risk'?`${x.axis} · مستوى الإجابة ${x.value} من 4`:type==='doc'?'وثيقة مقترحة للإنشاء أو التحديث':'مرتبة بحسب الأثر والحاجة إلى المعالجة'}</span></div></div>`).join('');return `<div class="panel-title"><div class="axis-icon">${icon('report')}</div><div><h3>نتيجة جاهزية الاستدامة</h3><p>نتيجة استرشادية من 100 تساعد على ترتيب الحوار والوثائق والأولويات</p></div></div><div class="result-shell"><section class="result-summary"><div class="score-ring" style="--score:${r.overall}"><div><strong>${r.overall}%</strong><span>جاهزية الاستدامة</span></div></div><div>${familyMarkup}<h3>${r.label}</h3><p>${r.desc}</p><div class="result-kpis"><div class="result-kpi"><small>نسبة الأسئلة المحتسبة</small><strong>${r.confidence}%</strong></div><div class="result-kpi"><small>أقوى محور</small><strong>${r.strongest.title}</strong></div><div class="result-kpi"><small>الأولوية الآن</small><strong>${r.weakest.title}</strong></div></div></div></section>${valuationResultMarkup(r.valuation)}<section class="axis-results">${axisHtml}</section><div class="result-grid"><section class="result-card"><h3>أهم المخاطر والفجوات</h3><div class="risk-list">${list(r.risks,'risk')}</div></section><section class="result-card"><h3>وثائق مقترحة</h3><div class="doc-list">${list(r.docs,'doc')}</div></section><section class="result-card"><h3>أهم الأولويات</h3><div class="priority-list">${list(r.priorities,'priority')}</div></section><section class="result-card"><h3>مواد تناسب نتيجة التشخيص</h3><div class="priority-list">${knowledgeForAxis(r.weakest.id).map((x,i)=>`<div class="result-item"><div class="result-index">${i+1}</div><div><strong>${x.title}</strong><span>${x.source} · ${x.year}</span></div></div>`).join('')}</div></section></div><div class="method-card"><strong>طريقة حساب النتيجة:</strong> يحسب كل محور من الأسئلة المناسبة لحالة العائلة بحسب أهمية السؤال، ثم يحسب المتوسط بين المحاور، يستبعد الحساب الأسئلة التي اختير لها «لا ينطبق»، ويضاف محور الوقف عند وجود وقف أو رغبة في دراسته، النتيجة استرشادية وتستخدم لترتيب الحوار والأولويات</div><div class="result-footer"><div><h3>حفظ النتيجة</h3><p>احفظ النتيجة كصورة، أو حمل التقرير بصيغة PDF.</p><div class="print-filename">اسم الملف المقترح: <strong>${escapeHtml(reportFileName())}</strong></div></div><div class="result-actions"><button class="btn ghost" id="restartBtn">إعادة التشخيص</button><button class="btn ghost" id="imageBtn">${icon('report')} حفظ النتيجة كصورة</button><button class="btn secondary" id="printBtn">${icon('print')} تحميل التقرير بصيغة PDF</button></div></div></div>`}
function knowledgeForAxis(axisId){const map={purpose:['pwc2025','imd'],charter:['law11','qadha-charter-2026','fbcg-code'],ownership:['ncfb-valuation-2026','law11'],company:['ncfb-valuation-2026','ifc'],succession:['ifc','insead'],wealth:['rajhiwaqf','masic'],resilience:['ncfb-valuation-2026','kpmg2025']};return (map[axisId]||['ifc','pwc2025']).map(id=>knowledgeData.find(x=>x.id===id)).filter(Boolean)}
function renderDiagnostic(){
 const s=steps();if(state.step>=s.length)state.step=s.length-1;
 renderStepTabs();updateProgress();
 const current=s[state.step];
 $('diagPanel').innerHTML=current.id==='profile'?profilePanel():current.id==='result'?resultPanel():axisPanel(axes.find(a=>a.id===current.id));
 bindPanel();enhanceResultActions();
}
const deferredRenderers=Object.create(null);
function renderWhenNear(sectionId,render){
 const section=$(sectionId);if(!section)return;
 let rendered=false;
 const run=()=>{if(rendered)return;rendered=true;render()};
 deferredRenderers[sectionId]=run;
 if(!('IntersectionObserver'in window)){run();return}
 const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){observer.disconnect();run()}},{rootMargin:'800px 0px'});
 observer.observe(section);
}
function initDeferredContent(){
 renderWhenNear('knowledge',()=>{setupKnowledgeFilters();renderKnowledge()});
 renderWhenNear('cases',renderCases);
 renderWhenNear('tools',renderTools);
 renderWhenNear('centers',renderCenters);
}
function prepareAnchorTarget(id){
 const sectionId=id==='emtidad-templates'?'tools':id;
 deferredRenderers[sectionId]?.();
}
function bindTopNavigation(){
 document.querySelectorAll('.top-nav a[href^="#"]').forEach(anchor=>anchor.addEventListener('click',event=>{
  const hash=anchor.getAttribute('href');
  if(!hash||hash==='#')return;
  const id=decodeURIComponent(hash.slice(1));
  const target=document.getElementById(id);
  if(!target)return;
  event.preventDefault();
  prepareAnchorTarget(id);
  if(location.hash!==hash)history.pushState(null,'',hash);
  requestAnimationFrame(()=>requestAnimationFrame(()=>target.scrollIntoView({behavior:'smooth',block:'start'})));
 }));
}
function stabilizeInitialHash(){
 const expectedHash=location.hash;
 if(!expectedHash||expectedHash==='#')return;
 const id=decodeURIComponent(expectedHash.slice(1));
 prepareAnchorTarget(id);
 const target=document.getElementById(id);
 if(!target)return;
 let lastHeight=0,stableChecks=0,checks=0;
 const align=()=>{
  if(location.hash!==expectedHash)return;
  const root=document.documentElement;
  const height=root.scrollHeight;
  stableChecks=height===lastHeight?stableChecks+1:0;
  lastHeight=height;
  const offset=parseFloat(getComputedStyle(root).scrollPaddingTop)||0;
  const destination=Math.max(0,target.getBoundingClientRect().top+window.scrollY-offset);
  const previousBehavior=root.style.scrollBehavior;
  root.style.scrollBehavior='auto';
  window.scrollTo(0,destination);
  root.style.scrollBehavior=previousBehavior;
  checks++;
  if(stableChecks<4&&checks<20)setTimeout(align,100);
 };
 if(document.readyState==='complete')align();
 else window.addEventListener('load',align,{once:true});
}
if($('modalClose')&&$('modal')){
 $('modalClose').addEventListener('click',()=>$('modal').hidden=true);
 $('modal').addEventListener('click',e=>{if(e.target===$('modal'))$('modal').hidden=true});
}
load();
if($('statsGrid'))renderStats();
if($('axisPreview'))renderAxesPreview();
if($('diagPanel'))renderDiagnostic();
setupDiagnosticStorageControls();
initDeferredContent();bindTopNavigation();stabilizeInitialHash();
